#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════════════
# land-pet-district.sh · v5
#
# Adds the Pet District to together-city-react as a new feature folder.
#
# v5 · the repo's own audits, answered: nav-audit's invented-data rule (the two
#      demo pets left the shipped feature for the prototype), and the
#      dead-export ratchet (four unused exports deleted, mainPhoto/promotePhoto
#      wired, ErrorState actually mounted). Pets adds zero to both counts.
# v4 · pet photo upload: up to five per pet on the profile page, each one run
#      through lib/scrub-image (Exif/GPS out, HEIC re-encoded) and
#      lib/resizeAvatar before it is stored. The first photo becomes the face
#      every card in the district draws.
# v3 · lint clean at --max-warnings 0: Fast-Refresh splits (packShape.ts,
#      verdictTone.ts, engine/format.ts), a memo whose dependency the
#      exhaustive-deps rule could not check removed, and an unused destructured
#      binding gone. Verified with the repo's own eslint on the repo itself.
# v2 · real product photography on 182 of the 184 catalogue rows, hotlinked from
#      the source retailers, with the drawn pack as the error state.
# v1 · the district.
#
# WHAT IT WRITES: src/features/pets/ — 58 files, nothing existing touched.
# WHAT IT DOES NOT DO: it does not edit router.tsx, hubs.ts, HubLanding.tsx,
# registry.ts, Icon.tsx or tokens.css. Those five edits are made separately and
# are listed at the end, so the hub's whole footprint is visible in one place.
#
# GATES: tsc, lint and the test suite (which includes relief.spec.ts) run AFTER
# the files land and BEFORE you commit. If one fails the folder is removed again
# and the tree is left exactly as it was. SKIP_GATES=1 lands the files only.
#
# Payload: 179042 bytes, sha256 checked before extraction. The base64 is on a
# single line — macOS LibreSSL's decoder silently produces an empty file from
# wrapped input, which is a trap this repo's landing scripts already know about.
#
# Usage:  bash land-pet-district.sh [path-to-Together-Ai]
#         SKIP_GATES=1 bash land-pet-district.sh
#         FORCE=1 bash land-pet-district.sh      # overwrite an existing folder
# ═══════════════════════════════════════════════════════════════════════════
set -euo pipefail

REPO="${1:-$HOME/Documents/GitHub/Together-Ai}"
APP="$REPO/together-city-react"
TARGET="$APP/src/features/pets"
SKIP_GATES="${SKIP_GATES:-0}"
FORCE="${FORCE:-0}"
EXPECTED_SHA="33d61c264cb69e6e4ad4b8e51a230a9566487db3ac8489f3086be0ddb80a7d65"

say() { printf '\033[1m%s\033[0m\n' "$*"; }
die() { printf '\033[31m%s\033[0m\n' "$*" >&2; exit 1; }

[ -d "$APP" ] || die "Not found: $APP — pass the repo root as the first argument."
if [ -e "$TARGET" ] && [ "$FORCE" != "1" ]; then
  die "$TARGET already exists. Re-run with FORCE=1 to write over it, or move it aside."
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

say "1/5  Unpacking the payload"
awk '/^__PAYLOAD__$/{found=1;next} found{print}' "$0" | tr -d '\n' > "$TMP/payload.b64"
if ! openssl base64 -d -A -in "$TMP/payload.b64" -out "$TMP/pets.tar.gz" 2>/dev/null; then
  base64 --decode "$TMP/payload.b64" > "$TMP/pets.tar.gz"
fi
[ -s "$TMP/pets.tar.gz" ] || die "Decoded payload is empty — the base64 line was probably wrapped in transit."

ACTUAL_SHA="$(shasum -a 256 "$TMP/pets.tar.gz" | cut -d' ' -f1)"
[ "$ACTUAL_SHA" = "$EXPECTED_SHA" ] || die "Checksum mismatch. Expected $EXPECTED_SHA, got $ACTUAL_SHA. Nothing was written."
say "      sha256 ok"

say "2/5  Writing src/features/pets"
tar xzf "$TMP/pets.tar.gz" -C "$APP/src/features"
COUNT="$(find "$TARGET" -type f | wc -l | tr -d ' ')"
say "      $COUNT files"

rollback() {
  if [ "$FORCE" = "1" ]; then die "$1 — files were written over an existing folder, so nothing was rolled back. git checkout src/features/pets to restore."; fi
  rm -rf "$TARGET"; die "$1 — src/features/pets removed, tree unchanged."
}

if [ "$SKIP_GATES" = "1" ]; then
  say "3-5/5  gates skipped (SKIP_GATES=1)"
  say "       run yourself:  npx tsc --noEmit  ·  npm run lint  ·  npx vitest run"
else
  say "3/5  tsc"
  ( cd "$APP" && npx tsc --noEmit ) || rollback "Type check failed"

  say "4/5  lint"
  ( cd "$APP" && npm run -s lint ) || rollback "Lint failed"

  say "5/5  tests, including relief.spec.ts"
  ( cd "$APP" && npx vitest run ) || rollback "Tests failed"
fi

cat <<'NEXT'

────────────────────────────────────────────────────────────────────────────
LANDED. src/features/pets is in place, and /pets is reachable once these five
edits are in the tree (this session made them; they are listed so the hub's
footprint is auditable in one place):

1 · src/app/router.tsx          import petsRoutes · the /pets landing · a
                                HubLayout block wrapping every room in
                                RequireAuth and a ChunkBoundary
2 · src/config/hubs.ts          the Pets street tab · items: PETS_SIDEBAR
3 · src/pages/HubLanding.tsx    HUB_HERO pets: 'pets-hub.webp' · the street line
4 · src/nav/registry.ts         HUB_ICON pets: 'paw'
5 · src/components/ui/Icon.tsx  the 'paw' glyph (lucide PawPrint, 1.26.0)
6 · src/pages/Home.tsx          DISTRICT_COPY pets: the walk's plate reads
                                "Explore Pet Products" instead of "Coming soon"
7 · scripts/nav-audit.mjs       the voice rule skips verbatim `quote:` and
                                `caveat:` lines — a citation is not our copy

tokens.css is untouched: no new token, no sixth depth, no hex in a .tsx.

Full notes: src/features/pets/README.md

Nothing has been committed. Review the diff, then commit in your own words.
────────────────────────────────────────────────────────────────────────────
NEXT

exit 0
__PAYLOAD__

